failure.message:
AssertionError: expected 200, got 400: {"detail":"Postmark account is still pending approval — right now it can only send to addresses on your own domain (@byrd-co.com). Request approval in the Postmark dashboard, then this email will go out. Raw error: [412] While your account is pending approval, all recipient addresses must share the same domain as the 'From' address. The domain of the 'From' address is 'mail.byrd-co.com', but you are attempting to send email to the following domain(s): 'byrd-co.com'."}
assert 400 == 200
 +  where 400 = <Response [400]>.status_code
